// pre-rendered to WebP (vb = the drawing's box). The front view lays it straight on (the front view is a fixed standing
// diagram); the side view draws each body part's piece through that part's rest-pose frame so it follows the ragdoll.
const SKINART={"front": {"vb": [120.0, 50.0, 150.0, 440.0], "src": "data:image/webp;base64,"}, "side": {"vb": [160.0, 50.0, 90.0, 440.0], "src": "data:image/webp;base64,"}, "arm": {"vb": [178.0, 132.0, 44.0, 192.0], "src": "data:image/webp;base64,"}, "shortsF": {"vb": [150.0, 244.0, 90.0, 64.0], "src": "data:image/webp;base64,"}, "shortsS": {"vb": [160.0, 244.0, 70.0, 62.0], "src": "data:image/webp;base64,"}, "back": {"vb": [120.0, 50.0, 150.0, 440.0], "src": "data:image/webp;base64,"}, "shortsB": {"vb": [150.0, 244.0, 90.0, 64.0], "src": "data:image/webp;base64,"}};
const SKINPX=2.43;
const SKINBMP={};
// skin grain (pores, fine mottling): a 128 px noise tile from a fixed-seed generator (never Math.random, so it doesn't
// shift the simulation's random sequence), drawn at 0.1 cm per pixel: pores are ≈0.1–0.3 mm, so this is the
// visible texture of the skin rather than single pores
const SKINGRAIN=(function(){const N=128,cv=document.createElement('canvas');cv.width=cv.height=N;const x=cv.getContext('2d'),d=x.createImageData(N,N);let s=1234567;const r=()=>(s=(s*16807)%2147483647)/2147483647;
  for(let i=0;i<N*N;i++){const v=r(),o=i*4;if(v<0.5){d.data[o]=60;d.data[o+1]=28;d.data[o+2]=16;d.data[o+3]=Math.round((0.5-v)*2*70);}else if(v>0.93){d.data[o]=255;d.data[o+1]=236;d.data[o+2]=220;d.data[o+3]=Math.round((v-0.93)/0.07*45);}}
  x.putImageData(d,0,0);return cv;})();
// load each drawing and bake the grain into the skin layers once (pattern fills every frame cost too much on phones)
(function(){for(const k in SKINART){const a=SKINART[k],vb=a.vb,im=new Image();im.src=a.src;
  (im.decode?im.decode():Promise.resolve()).catch(()=>{}).then(()=>{let cv=im;
    if(!/^shorts/.test(k)){try{cv=document.createElement('canvas');cv.width=im.naturalWidth;cv.height=im.naturalHeight;const x=cv.getContext('2d');x.drawImage(im,0,0);
      x.globalCompositeOperation='source-atop';const pt=x.createPattern(SKINGRAIN,'repeat');const k2=im.naturalWidth/(vb[2]/SKINPX)*0.1;if(pt.setTransform)pt.setTransform(new DOMMatrix().scale(k2));x.fillStyle=pt;x.globalAlpha=0.55;x.fillRect(0,0,cv.width,cv.height);}catch(e){cv=im;}}
    SKINBMP[k]={cv,x0:(vb[0]-195)/SKINPX,y0:(vb[1]-483)/SKINPX,w:vb[2]/SKINPX,h:vb[3]/SKINPX};if(typeof skinArtReady==='function')skinArtReady();});}})();
